  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly or implicitly takes personal responsibility for a specific action, achievement, or policy outcome, often highlighting their individual or collective role in securing funding, passing legislation, or advocating for a cause.",
    "clarification": "Credit-claiming is identified when a senator uses language that directly or indirectly attributes a positive outcome to their efforts. This can include phrases like 'I secured,' 'I fought for,' 'I introduced,' or 'I am proud to announce.' The focus is on the senator's personal or direct involvement in achieving a result that benefits their constituents, state, or a specific group. It often involves tangible outcomes such as funding, legislative passage, or program implementation.",
    "positive_examples": [
      {
        "document_id": "89",
        "explanation": "Senator Dorgan explicitly states that he authored legislation that created the National Center designation for Bismarck State College and takes pride in the program. This is a clear example of credit-claiming as he directly attributes the achievement to his legislative efforts."
      },
      {
        "document_id": "3482",
        "explanation": "Sens. Mikulski and Cardin announce federal funding for Allegany County firefighters, with Senator Mikulski explicitly stating her role in securing the funds through her position on the Homeland Security Appropriations Subcommittee. This demonstrates credit-claiming as she highlights her direct involvement in the funding process."
      },
      {
        "document_id": "4585",
        "explanation": "Senator Schumer announces federal fire grants for Westchester County and explicitly states his role in pushing for additional funding and securing the grants. This is credit-claiming as he directly links the outcome to his advocacy efforts."
      }
    ],
    "negative_clarification": "Not credit-claiming occurs when a senator discusses issues, policies, or events without explicitly or implicitly taking personal credit for the outcomes. This includes general statements of support, criticism, or advocacy that do not tie a specific achievement or result to their individual actions. It also includes cases where the senator is merely reporting on events, expressing opinions, or discussing broader policy goals without claiming responsibility for tangible results.",
    "negative_examples": [
      {
